        if len(lst)!=2: continue
        ds=sorted((min(abs(r-av[0])+abs(cc-av[1]) for r,cc in ob),c,ob) for c,ob in lst)
        score=ds[-1][0]
        if bestscore is None or score<bestscore:
            bestscore=score; target=(ds[-1][1],ds[-1][2])
    tc,to=target
